                        <p className={cn("text-sm", isDark ? "text-zinc-500" : "text-slate-500")}>This user hasn't referred anyone yet.</p>
                      </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className={cn("text-center py-8", isDark ? "text-zinc-500" : "text-slate-500")}>No data available</div>
