                      className={cn("w-full bg-black/40 border rounded-xl px-4 py-2.5", isDark ? "bg-[#0A0B1A] border-white/10 text-white focus:bg-[#11162C]" : "bg-white border-slate-200 text-slate-900 focus:bg-slate-50")}
