                                    </button>
                                  </div>
                                </>
                              )}
                            </div>
                          )}
                        </td>
                        <td className="p-4">
                          <div className={cn("text-sm", isDark ? "text-zinc-300" : "text-slate-600")}>{ip.user.name}</div>
