              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className={cn("border rounded-3xl p-6 max-w-md w-full shadow-md relative overflow-hidden", isDark ? "bg-white/[0.02] border-white/10" : "bg-white border-slate-200")}
            >
