                    isDark ? "bg-cyan-600 hover:bg-cyan-700 text-white hover:shadow-[0_0_20px_rgba(8,145,178,0.3)]" : "bg-cyan-600 hover:bg-cyan-700 text-white"
                  )}
                >
                  {isSnapshotting ? (
                    <><RefreshCw className="w-4 h-4 animate-spin" /> Processing...</>
